changeSet.sql:
ALTER TABLE procurement_approval_policy
 ADD COLUMN IF NOT EXISTS priority INTEGER NOT NULL DEFAULT 100;
ALTER TABLE procurement_approval_policy
 ADD COLUMN IF NOT EXISTS conditions TEXT NOT NULL DEFAULT '[]';
ALTER TABLE procurement_approval_instance
 ADD COLUMN IF NOT EXISTS estimated_net_amount NUMERIC(19,4);
ALTER TABLE procurement_approval_instance
 ADD COLUMN IF NOT EXISTS currency VARCHAR(3);
CREATE UNIQUE INDEX IF NOT EXISTS uk_proc_approval_active_priority
 ON procurement_approval_policy(company_id,document_type,priority)
 WHERE status='ACTIVE';
DROP INDEX IF EXISTS uk_proc_approval_active;
